question:
Write the output of the following program
#define MAX(A,B) ((A)>(B)) ? A:B
void main(){
  int i=1;
  int j=2;
  int val=max(++i,++j);
  printf("%d",val);
}

Write the output of the following program
int sum(int val){
  static int myResult=0;
  myResult += val;
  return myResult;
}
void main(){
  int i, value;
  for(i=1;i<10;i++)
    value=sum(i);
  printf("%d",value);
}
